const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');
async function main() {
  // Transient after commit: retried with same receipt, single debit.
  { const ledger = new Ledger(); const seen = []; let fails = 2;
    const s = new PaymentService(ledger, { acknowledge: async r => { seen.push(r); if (fails-- > 0) throw new Transient('t'); } });
    const r = await s.pay('t', 'k', 50, 3);
    assert.equal(ledger.entries.length, 1); assert.equal(seen.length, 3);
    assert.ok(seen.every(x => x === r));
    assert.equal(await s.pay('t', 'k', 50), r); assert.equal(ledger.entries.length, 1);
    await assert.rejects(s.pay('t', 'k', 51), /key conflict/); assert.equal(ledger.entries.length, 1);
    await s.pay('t2', 'k', 51); await s.pay('t', 'k2', 51); assert.equal(ledger.entries.length, 3);
  }
  // Exhaustion preserves final error; non-transient not retried.
  { const ledger = new Ledger(); let n = 0; const errs = [];
    const s = new PaymentService(ledger, { acknowledge: async () => { const e = new Transient('t' + ++n); errs.push(e); throw e; } });
    await assert.rejects(s.pay('a', 'b', 1, 2), e => e === errs[1]); assert.equal(n, 2);
    await assert.rejects(s.pay('a', 'b', 1, 2), e => e === errs[3]); assert.equal(ledger.entries.length, 1);
    let m = 0; const boom = new Error('boom');
    const s2 = new PaymentService(new Ledger(), { acknowledge: async () => { m++; throw boom; } });
    await assert.rejects(s2.pay('a', 'b', 1, 5), e => e === boom); assert.equal(m, 1);
  }
  // Concurrency.
  { const ledger = new Ledger(); const s = new PaymentService(ledger, { acknowledge: async () => {} });
    const rs = await Promise.all([1, 2, 3].map(() => s.pay('t', 'k', 9)));
    assert.equal(ledger.entries.length, 1); assert.ok(rs.every(r => r === rs[0]));
  }
  // Validation before any action.
  { const ledger = new Ledger(); let acks = 0; const s = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    for (const args of [['', 'k', 1], ['t', '', 1], ['t', 'k', 1.5], ['t', 'k', -1], ['t', 'k', 1, 0], ['t', 'k', 1, 6], ['t', 'k', 1, 2.5], ['t', 'k', NaN]])
      await assert.rejects(s.pay(...args), /^Error: invalid payment$/);
    assert.equal(ledger.entries.length, 0); assert.equal(acks, 0);
  }
}
module.exports = main();

